int handle_invalid_entry(struct fuse_conn *fc, unsigned int size, struct fuse_copy_state *cs) {
    char *name = NULL;
    struct output_data {
        char *name;
        size_t name_len;
        unsigned int hash;
    } *out = NULL;

    if (!fc || !cs) {
        return -EINVAL;
    }

    if (size > SIZE_MAX / sizeof(char)) {
        return -EINVAL;
    }

    name = malloc(size);
    if (!name) {
        return -ENOMEM;
    }

    if (fuse_copy_in(cs, name, size, 0) < 0) {
        free(name);
        return -EFAULT;
    }

    out = malloc(sizeof(*out));
    if (!out) {
        free(name);
        return -ENOMEM;
    }

    out->name = name;
    out->name_len = strnlen(name, size);

    if (out->name_len == size) {
        free(name);
        free(out);
        return -ENAMETOOLONG;
    }

    out->hash = compute_hash(name, out->name_len);

    int result = reverse_invalid_entry(fc, out);

    free(out->name);
    free(out);

    return result;
}
